INSERT INTO categories (slug, name_en, name_fr, name_ar, description_en, description_fr, description_ar, sort_order) VALUES
('silos',   'Silos Collection',   'Collection Silos',   'مجموعة سيلوس',   'Elongated picket-shaped ceramic tiles (10x30 cm) with artisanal glazed finishes.',        'Carreaux en forme de piquet allongé (10x30 cm) avec des finitions émaillées artisanales.',        'بلاط سيراميك بشكل لقطة مستطيلة (10×30 سم) بتشطيبات مزججة حرفية.',        1),
('atelier', 'Atelier Collection', 'Collection Atelier', 'مجموعة أتيليه',  'Artisan-crafted leaf-shaped tiles (10x30 cm) with embossed relief and metallic finishes.', 'Carreaux en forme de feuille (10x30 cm) avec textures en relief et finitions métalliques.', 'بلاط على شكل ورقة (10×30 سم) بنقوش بارزة وتشطيبات معدنية.',              2),
('ducal',   'Ducal Collection',   'Collection Ducal',   'مجموعة دوكال',   'Classic subway-style rectangular tiles (10x30 cm) with an aged handmade look.',           'Carreaux rectangulaires de style métro (10x30 cm) avec un aspect vieilli fait main.',      'بلاط مستطيل بأسلوب المترو (10×30 سم) بمظهر عتيق مصنوع يدويًا.',           3),
('leaf',    'Leaf Collection',    'Collection Leaf',    'مجموعة ليف',     'Leaf-shaped tiles (15x30 cm) in vibrant glazed and metallic finishes.',                    'Carreaux en forme de feuille (15x30 cm) aux finitions émaillées et métalliques vibrantes.','بلاط على شكل ورقة (15×30 سم) بتشطيبات مزججة ومعدنية زاهية.',              4),
('gonos',   'Gonos Collection',   'Collection Gonos',   'مجموعة غونوس',   'Elongated hexagonal tiles (15x30 cm) with playful decorative motifs.',                    'Carreaux hexagonaux allongés (15x30 cm) avec des motifs décoratifs ludiques.',             'بلاط سداسي مستطيل (15×30 سم) بزخارف مرحة.',                               5),
('chic',    'Chic Collection',    'Collection Chic',    'مجموعة شيك',     'Moroccan-inspired scallop and arabesque tiles (20x20 cm) in bold glazed and metallic finishes.','Carreaux en écaille et arabesque d''inspiration marocaine (20x20 cm).',          'بلاط صدفي وأرابيسك مستوحى من المغرب (20×20 سم).',                          6),
('kronfel', 'Kronfel Collection', 'Collection Kronfel', 'مجموعة كرونفل',  'Traditional hand-painted square tiles (20x20 cm) with rich ornamental patterns.',         'Carreaux carrés peints à la main (20x20 cm) avec riches motifs ornementaux.',              'بلاط مربع مطلي يدويًا (20×20 سم) بزخارف زخرفية غنية.',                   7),
('casbah',  'Casbah Collection',  'Collection Casbah',  'مجموعة قصبة',    'Andalusian-style hand-painted tiles (20x20 cm) with botanical motifs.',                   'Carreaux peints à la main de style andalou (20x20 cm) avec motifs botaniques.',            'بلاط بالأسلوب الأندلسي مرسوم يدويًا (20×20 سم) بزخارف نباتية.',           8),
('yasmine', 'Yasmine Collection', 'Collection Yasmine', 'مجموعة ياسمين',  'Ottoman-inspired hand-painted tiles (20x20 cm) with intricate floral arabesque.',         'Carreaux peints à la main d''inspiration ottomane (20x20 cm) avec arabesque florale.',     'بلاط مستوحى من العثمانية مرسوم يدويًا (20×20 سم) بأرابيسك زهري.',         9);
