-- ── 0. COLUMN SAFETY ─────────────────────────────────────────
ALTER TABLE products ADD COLUMN IF NOT EXISTS base_price    numeric(10,2) NOT NULL DEFAULT 0;
ALTER TABLE products ADD COLUMN IF NOT EXISTS images        text[]        NOT NULL DEFAULT '{}';
ALTER TABLE products ADD COLUMN IF NOT EXISTS is_active     boolean       NOT NULL DEFAULT true;
ALTER TABLE products ADD COLUMN IF NOT EXISTS is_featured   boolean       NOT NULL DEFAULT false;
ALTER TABLE products ADD COLUMN IF NOT EXISTS description_en text;
ALTER TABLE products ADD COLUMN IF NOT EXISTS description_fr text;
ALTER TABLE products ADD COLUMN IF NOT EXISTS description_ar text;
ALTER TABLE products ADD COLUMN IF NOT EXISTS updated_at    timestamptz   DEFAULT now();
ALTER TABLE categories ADD COLUMN IF NOT EXISTS description_en text;
ALTER TABLE categories ADD COLUMN IF NOT EXISTS description_fr text;
ALTER TABLE categories ADD COLUMN IF NOT EXISTS description_ar text;
ALTER TABLE categories ADD COLUMN IF NOT EXISTS image_url      text;
ALTER TABLE categories ADD COLUMN IF NOT EXISTS sort_order     int DEFAULT 0;
ALTER TABLE product_variants ADD COLUMN IF NOT EXISTS name_en        text;
ALTER TABLE product_variants ADD COLUMN IF NOT EXISTS name_fr        text;
ALTER TABLE product_variants ADD COLUMN IF NOT EXISTS name_ar        text;
ALTER TABLE product_variants ADD COLUMN IF NOT EXISTS sku            text;
ALTER TABLE product_variants ADD COLUMN IF NOT EXISTS price_modifier  numeric(10,2) DEFAULT 0;
ALTER TABLE product_variants ADD COLUMN IF NOT EXISTS stock          int DEFAULT 0;
ALTER TABLE product_variants ADD COLUMN IF NOT EXISTS color_hex      text;

-- ── 1. WIPE EVERYTHING ───────────────────────────────────────
DELETE FROM order_items;
DELETE FROM orders;
DELETE FROM product_variants;
DELETE FROM products;
DELETE FROM categories;

